def valid_di_permutation_count(s):
    mod=10**9+7;dp=[1]
    for char in s:
        n=len(dp);next_row=[0]*(n+1)
        if char=='I':
            total=0
            for rank in range(n+1):
                if rank:total+=dp[rank-1]
                next_row[rank]=total%mod
        else:
            total=0
            for rank in range(n,-1,-1):
                if rank<n:total+=dp[rank]
                next_row[rank]=total%mod
        dp=next_row
    return sum(dp)%mod

